    //   Invariant:
    //     1) 1 <= i <= arr.len()
    //     2) max_val is at least every element in arr[0 .. i]
    //     3) max_val equals some element in   arr[0 .. i]
    //   Decreases: arr.len() - i
    //
    #[invariant(1 <= i && i <= arr.len())]
    #[invariant(forall(|j: usize| j < i ==> max_val >= arr[j]))]
    #[invariant(exists(|j: usize| j < i && max_val == arr[j]))]
    #[decreases(arr.len() - i)]
    while i < arr.len() {
        let v = arr[i];
        if v > max_val {
            max_val = v;
        }
        i = i + 1;
    }

    // at this point i == arr.len(), so by the post‐loop invariant:
    //   * max_val >= arr[j] for all j < arr.len()
    //   * there is some j < arr.len() with max_val == arr[j]
    max_val
